var o=[{title:`Escalas de tempo`,text:`Um microciclo é um período curto que se repete, muitas vezes uma semana. Um mesociclo é um bloco de várias semanas com um foco principal. Um macrociclo abrange uma época ou um período de objetivo mais longo. Estes nomes ajudam no planeamento, e a sua duração varia de pessoa para pessoa.`},{title:`Três abordagens`,text:`A progressão linear altera as variáveis lentamente numa direção geral, por exemplo de mais repetições com cargas mais leves para menos repetições com cargas mais pesadas. O treino ondulatório altera com mais frequência os objetivos de repetições ou a intensidade, talvez pesado à segunda e moderado à quinta. A periodização em blocos executa fases uma após a outra, cada uma centrada numa capacidade específica.`},{title:`O que mostra a investigação`,text:`Os estudos que comparam planos com o mesmo volume encontram possíveis vantagens de força para o treino periodizado em relação ao não periodizado, e para os planos ondulatórios em pessoas treinadas. As diferenças no crescimento muscular são menos consistentes. O posicionamento do ACSM 2026 não encontrou um benefício consistente para o crescimento muscular só por acrescentar periodização. Um plano mais complexo não é automaticamente melhor.`},{title:`Exemplo`,text:`Se for iniciante, repita um pequeno conjunto de exercícios principais durante seis semanas e aumente lentamente as repetições ou a carga. Torne um exercício mais difícil à medida que a técnica melhora. Praticantes mais avançados podem fazer três semanas de prática com maior volume, depois uma fase mais pesada e uma semana de recuperação mais leve, consoante a sua resposta.`},{title:`Usar o TrainUp`,text:`O seu plano abrange 4 semanas, e a semana 4 é uma semana de descarga mais leve. O seu objetivo, o seu nível de condição física e o seu feedback contam mais do que um calendário elaborado. Só recebe um plano novo quando o gera de novo, e este muda um passo de cada vez com base nos seus treinos recentes.`}];var s=[{label:`Revisão sistemática da periodização e dos resultados do treino`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Orientações do ACSM sobre o modelo de progressão`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};